/* gap8/main.c: run aif_zoi_v2 on the GAP8 cluster and count cycles per stage.
 *
 * Inputs: the frames in trace_data.h (poses and detector boxes of a recorded
 * flight, generated by tools/v2_c/make_gap8_trace.py). For every frame it runs
 * the detector-frame update and one plan from that frame's pose (the worst case:
 * in flight a replan happens on ~40% of the frames), checks the decision against
 * the Python one stored in the trace, and prints the cycles of each stage.
 *
 * The fabric controller only starts the cluster; everything runs on the cluster:
 * core 0 runs the algorithm, and the parallel kernels (evidence, beliefs,
 * planner IG and flight times) are spread over NB_CORES cores with pi_cl_team_fork.
 *
 * Build options (gap8/Makefile): NB_CORES (1 or 8), ZOI_V2_REFERENCE_KERNELS (1
 * faithful, 0 optimised), CL_FREQ_MHZ (only to convert cycles to ms in the printout).
 *
 * Written against the PMSIS API of the GAP SDK; not compiled here (no SDK on the
 * development machine). See GVSOC_GUIDE.md.
 */
#include <stdint.h>
#include <stdio.h>

#include "pmsis.h"

#include "trace_data.h"
#include "zoi_v2.h"

#ifndef NB_CORES
#define NB_CORES 8
#endif
#ifndef CL_FREQ_MHZ
#define CL_FREQ_MHZ 175
#endif

#if TRACE_GRID_N != ZOI_GRID_N
#error "trace_data.h was generated for another (rho, theta) grid size"
#endif

/* In L2 (globals of a PMSIS program go to L2 by default). 55 kB. */
static zoi_state_t st;

static const char *STAGE_NAMES[ZOI_N_STAGES] = {"geometry", "update", "beliefs", "planner IG", "planner T"};

/* ---- Parallel kernels on the cluster ---------------------------------- */

static zoi_kernel_fn g_fn;
static void *g_arg;

static void team_entry(void *arg)
{
    (void)arg;
    g_fn(g_arg, (int)pi_core_id(), NB_CORES);
}

static void cluster_fork(zoi_kernel_fn fn, void *arg)
{
    g_fn = fn;
    g_arg = arg;
    pi_cl_team_fork(NB_CORES, team_entry, NULL); /* returns when every core is done */
}

/* ---- Cycle counting --------------------------------------------------- */

static uint32_t stage_start[ZOI_N_STAGES];
static uint32_t frame_cycles[ZOI_N_STAGES];
static uint64_t total_cycles[ZOI_N_STAGES];
static uint32_t max_cycles[ZOI_N_STAGES];

static void profile(zoi_stage_t stage, int start)
{
    const uint32_t now = (uint32_t)pi_perf_read(PI_PERF_CYCLES);
    if (start)
        stage_start[stage] = now;
    else
        frame_cycles[stage] += now - stage_start[stage]; /* unsigned: wrap-safe */
}

static uint32_t ms_x100(uint64_t cycles)
{
    return (uint32_t)(cycles / ((uint64_t)CL_FREQ_MHZ * 10u)); /* hundredths of ms */
}

static void cluster_main(void *arg)
{
    (void)arg;
    pi_perf_conf(1 << PI_PERF_CYCLES);
    pi_perf_reset();
    pi_perf_start();

    if (NB_CORES > 1)
        zoi_fork = cluster_fork;
    zoi_profile = profile;

    zoi_config_t cfg;
    zoi_config_default(&cfg, TRACE_ENV, TRACE_DET);
    cfg.recall = TRACE_PARAMS[0];
    cfg.class_accuracy = TRACE_PARAMS[1];
    cfg.false_alarm = TRACE_PARAMS[2];
    cfg.table_context = TRACE_TABLE_CONTEXT;
    if (cfg.table_context) {
        cfg.desk_recall = TRACE_PARAMS[3];
        cfg.desk_false_alarm = TRACE_PARAMS[4];
        cfg.p_on_table = TRACE_PARAMS[5];
    }

    const uint32_t t_init = (uint32_t)pi_perf_read(PI_PERF_CYCLES);
    const int rc = zoi_init(&st, &cfg);
    const uint32_t init_cycles = (uint32_t)pi_perf_read(PI_PERF_CYCLES) - t_init;
    if (rc != 0) {
        printf("zoi_init failed (%d)\n", rc);
        return;
    }
    printf("aif_zoi_v2 on GAP8: %d cores, %s kernels, %d frames, state %u B, grid %d points, init %u cycles\n",
           NB_CORES, ZOI_V2_REFERENCE_KERNELS ? "reference" : "optimised", TRACE_N_FRAMES,
           (unsigned)sizeof(zoi_state_t), st.n_grid, (unsigned)init_cycles);
    printf("frame;geometry;update;beliefs;planner_IG;planner_T;total;plan_ok\n");

    int plans_ok = 0;
    for (int f = 0; f < TRACE_N_FRAMES; f++) {
        for (int s = 0; s < ZOI_N_STAGES; s++)
            frame_cycles[s] = 0;
        zoi_perception_frame(&st, &TRACE_POSE[f], &TRACE_BOXES[TRACE_BOX_START[f]], TRACE_BOX_COUNT[f]);
        const int k = zoi_plan(&st, &TRACE_POSE[f]);
        const int ok = (k == TRACE_PLAN[f]);
        plans_ok += ok;

        uint32_t sum = 0;
        for (int s = 0; s < ZOI_N_STAGES; s++) {
            sum += frame_cycles[s];
            total_cycles[s] += frame_cycles[s];
            if (frame_cycles[s] > max_cycles[s])
                max_cycles[s] = frame_cycles[s];
        }
        printf("%d;%u;%u;%u;%u;%u;%u;%d\n", f, (unsigned)frame_cycles[0], (unsigned)frame_cycles[1],
               (unsigned)frame_cycles[2], (unsigned)frame_cycles[3], (unsigned)frame_cycles[4], (unsigned)sum, ok);
    }

    uint64_t all = 0;
    printf("\nstage        mean cycles   max cycles   mean ms @%d MHz\n", CL_FREQ_MHZ);
    for (int s = 0; s < ZOI_N_STAGES; s++) {
        const uint64_t mean = total_cycles[s] / TRACE_N_FRAMES;
        all += mean;
        const uint32_t m = ms_x100(mean);
        printf("%-12s %11u  %11u   %u.%02u\n", STAGE_NAMES[s], (unsigned)mean, (unsigned)max_cycles[s], (unsigned)(m / 100),
               (unsigned)(m % 100));
    }
    const uint32_t m = ms_x100(all);
    printf("%-12s %11u  %11s   %u.%02u   (detector frame + one plan)\n", "total", (unsigned)all, "", (unsigned)(m / 100),
           (unsigned)(m % 100));
    printf("plans equal to Python: %d / %d\n", plans_ok, TRACE_N_FRAMES);
}

/* ---- Fabric controller ------------------------------------------------- */

static void app_main(void)
{
    struct pi_device cluster_dev;
    struct pi_cluster_conf conf;
    struct pi_cluster_task task;

    pi_cluster_conf_init(&conf);
    conf.id = 0;
    pi_open_from_conf(&cluster_dev, &conf);
    if (pi_cluster_open(&cluster_dev)) {
        printf("cluster open failed\n");
        pmsis_exit(-1);
    }
    pi_cluster_task(&task, cluster_main, NULL);
    task.stack_size = 8192;       /* core 0: the algorithm (largest frame ~3 kB) */
    task.slave_stack_size = 2048; /* cores 1..7: the kernels */
    pi_cluster_send_task_to_cl(&cluster_dev, &task);
    pi_cluster_close(&cluster_dev);
    pmsis_exit(0);
}

int main(void)
{
    return pmsis_kickoff((void *)app_main);
}
